INSERT INTO interns (id, sname, sterm, sInstitute, Hours, dateassignfrom, dateassignto, dateprefferedfrom, dateprefferedto, DateofInternship, Dateofentry, Address, Organizationname, Mentor, Designationanddepartment, punctuality, regularity, productivity, relationship_with_others, Initiative, Maturity, Confidence, Analytical_ability, abilityhardword, knowledge, Assignedwork, comments, HRperson, HRdesignation, Request_Form, Photograph, CV, Recommendation_Letter, CNIC_copy, Student_ID, Email, Degree, Location, iyear, Date_of_Submission, Cellnumber, confirmed, Waiting, status, GroupName, GroupTime, Assignment1, Assignment2, Assignment3, Assignment4, Assignment5, Supervisor, Department, Father_name, GroupN, Summer, Certificate_Period_Detail, Remarks, Assignments, ERPNO) VALUES (366, 'Hira Abdul Aziz', '4th Semester', 'Institute of Business Administration', NULL, '2016-06-15 00:00:00', '2016-08-13 00:00:00', NULL, NULL, NULL, '2016-05-31 00:00:00', 'C-201/1, Block 14, Gulistan-e-Johar, Karachi.', 'Institute of Business Administration', 'Mr. Muhammad Wali', 'Officer-Coordination', 9, 9, 9, 9, 9, 9, 9, 8, 9, 9, 'The work assigned to her was varied it included task like sending emails, content editing, updating facebook pages, conducting interviews of patients and making their case studies. She was sent to Ahram House where she was given task related to packing different items as well as task related to some paper work.', 'She was one of the most dedicated and hard working interns at AWT. We were delighted to work with her. Her work was accurate and was submitted on time. She was very approachable and friendly while conducting the patient’s interview. She may lack on her writing skills but her innovative ideas were gracefully welcomed.', 'Nisar Ahmed', 'Coordinator', NULL, NULL, NULL, NULL, NULL, NULL, 'hiraaziz2009@hotmail.com', 'BSEM', NULL, '2016', NULL, '0314-2575888', NULL, 0, 'completed', NULL, NULL, 0, 0, 0, 0, 0, NULL, NULL, 'Abdul Aziz', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO interns (id, sname, sterm, sInstitute, Hours, dateassignfrom, dateassignto, dateprefferedfrom, dateprefferedto, DateofInternship, Dateofentry, Address, Organizationname, Mentor, Designationanddepartment, punctuality, regularity, productivity, relationship_with_others, Initiative, Maturity, Confidence, Analytical_ability, abilityhardword, knowledge, Assignedwork, comments, HRperson, HRdesignation, Request_Form, Photograph, CV, Recommendation_Letter, CNIC_copy, Student_ID, Email, Degree, Location, iyear, Date_of_Submission, Cellnumber, confirmed, Waiting, status, GroupName, GroupTime, Assignment1, Assignment2, Assignment3, Assignment4, Assignment5, Supervisor, Department, Father_name, GroupN, Summer, Certificate_Period_Detail, Remarks, Assignments, ERPNO) VALUES (367, 'Syed Muhammad Ali Mohsin Naqvi', '5th Semester', 'Institute of Business Administration', NULL, '2016-06-15 00:00:00', '2016-08-13 00:00:00', NULL, NULL, NULL, '2016-06-02 00:00:00', 'Flat no AA-103, Welcome Centre, Block 19, Gulistan-e-Jauhar, Karachi.', 'Institute of Business Administration', 'Mr. Muhammad Wali', 'Officer-Coordination', 9, 9, 10, 9, 10, 9, 10, 9, 10, 9, 'He performed task like sending emails, content writing, managing facebook and twitter pages and writing patient’s story. He also hosted the closing ceremony of IBA interns. He performed some duties at Ahram house which include packing and some paper work.', 'He had a great knowledge of handling social media and web pages. He was also good in content writing and editing. He also knows how to work in a team. He was humorous and therefore need to maintain more serious attitude for his work.', 'Nisar Ahmed', 'Coordinator', NULL, NULL, NULL, NULL, NULL, NULL, 'alimohsinn@hotmail.com', 'BBA', NULL, '2016', NULL, '0342-2479528', NULL, 0, 'completed', NULL, NULL, 0, 0, 0, 0, 0, NULL, NULL, 'Syed Rizwan Hussain', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO interns (id, sname, sterm, sInstitute, Hours, dateassignfrom, dateassignto, dateprefferedfrom, dateprefferedto, DateofInternship, Dateofentry, Address, Organizationname, Mentor, Designationanddepartment, punctuality, regularity, productivity, relationship_with_others, Initiative, Maturity, Confidence, Analytical_ability, abilityhardword, knowledge, Assignedwork, comments, HRperson, HRdesignation, Request_Form, Photograph, CV, Recommendation_Letter, CNIC_copy, Student_ID, Email, Degree, Location, iyear, Date_of_Submission, Cellnumber, confirmed, Waiting, status, GroupName, GroupTime, Assignment1, Assignment2, Assignment3, Assignment4, Assignment5, Supervisor, Department, Father_name, GroupN, Summer, Certificate_Period_Detail, Remarks, Assignments, ERPNO) VALUES (368, 'Syed Hamza Ahmed Bukhari', '4th Semester', 'Institute of Business Administration', NULL, '2016-06-15 00:00:00', '2016-08-13 00:00:00', NULL, NULL, NULL, '2016-06-02 00:00:00', 'C-138, Block J, North Nazimabad, Karachi.', 'Institute of Business Administration', 'Mr. Muhammad Wali', 'Officer-Coordination', 9, 8, 9, 9, 9, 9, 8, 9, 9, 9, 'The intern was divided into a group of three. He was assigned different tasks on weekly basis. Such tasks included Outdoor work, which meant venturing across different departments (Healthcare, Rashan system, marriage assistance etc) and evaluating a report in a write-up or post form. These tasks also focused on indoor work which included Data entries and documentation of office work.', 'He was seen to be very energetic; He was effective in using his team working skills. We saw a lack of attentiveness in him but overall the originality of ideas presented by him made him one of the outstanding interns we had this year.', 'Nisar Ahmed', 'Coordinator', NULL, NULL, NULL, NULL, NULL, NULL, 'hamza00304@gmail.com', 'BBA', NULL, '2016', NULL, '0304-2510615', NULL, 0, 'completed', NULL, NULL, 0, 0, 0, 0, 0, NULL, NULL, 'Syed Muhammad Ahmed', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO interns (id, sname, sterm, sInstitute, Hours, dateassignfrom, dateassignto, dateprefferedfrom, dateprefferedto, DateofInternship, Dateofentry, Address, Organizationname, Mentor, Designationanddepartment, punctuality, regularity, productivity, relationship_with_others, Initiative, Maturity, Confidence, Analytical_ability, abilityhardword, knowledge, Assignedwork, comments, HRperson, HRdesignation, Request_Form, Photograph, CV, Recommendation_Letter, CNIC_copy, Student_ID, Email, Degree, Location, iyear, Date_of_Submission, Cellnumber, confirmed, Waiting, status, GroupName, GroupTime, Assignment1, Assignment2, Assignment3, Assignment4, Assignment5, Supervisor, Department, Father_name, GroupN, Summer, Certificate_Period_Detail, Remarks, Assignments, ERPNO) VALUES (369, 'Merwa Tariq', NULL, 'Institute of Business Administration', NULL, '2016-06-15 00:00:00', '2016-08-13 00:00:00', NULL, NULL, NULL, '2016-06-02 00:00:00', 'House no B-46, Block 13, Fb Area, Karachi.', 'Institute of Business Administration', 'Mr. Abdul Latif', 'Officer-OPD', 9, 9, 9, 8, 9, 9, 8, 8, 9, 9, 'She visited opd, dialysis centre, ultra sound dept., food distribution point, ration centre, ahram house, physiotherapy dept and Medical Superintendent Office. She assisted in writing and posting patient stories in the medical depts. and developing content for annual report regarding the various services provided by Alamgir. She further helped in filing and organizing in the administration dept and did her best with the official work of invitation letters of the concluding ceremony, etc.', 'She was respectful, obedient and punctual. She was a responsible team member and had strong writing abilities. She had a generally shy attitude yet worked creatively on the assigned tasks. Efficiency being a key trait of her performance and was always keen to learn.', 'Nisar Ahmed', 'Coordinator', NULL, NULL, NULL, NULL, NULL, NULL, 'merwatariq@gmail.com', 'BSEM', NULL, '2016', NULL, '0307-2497077', NULL, 0, 'completed', NULL, NULL, 0, 0, 0, 0, 0, NULL, NULL, 'Tariq Ejaz', NULL, NULL, NULL, NULL, NULL, NULL);
