INSERT INTO interns (id, sname, sterm, sInstitute, Hours, dateassignfrom, dateassignto, dateprefferedfrom, dateprefferedto, DateofInternship, Dateofentry, Address, Organizationname, Mentor, Designationanddepartment, punctuality, regularity, productivity, relationship_with_others, Initiative, Maturity, Confidence, Analytical_ability, abilityhardword, knowledge, Assignedwork, comments, HRperson, HRdesignation, Request_Form, Photograph, CV, Recommendation_Letter, CNIC_copy, Student_ID, Email, Degree, Location, iyear, Date_of_Submission, Cellnumber, confirmed, Waiting, status, GroupName, GroupTime, Assignment1, Assignment2, Assignment3, Assignment4, Assignment5, Supervisor, Department, Father_name, GroupN, Summer, Certificate_Period_Detail, Remarks, Assignments, ERPNO) VALUES (373, 'Bilal Shuja Zaidi', NULL, 'Institute of Business Administration', NULL, '2016-06-15 00:00:00', '2016-08-13 00:00:00', NULL, NULL, NULL, '2016-06-04 00:00:00', 'E-48, Block B, North Nazimabad, Karachi.', 'Institute of Business Administration', 'Mr. Muhammad Wali', 'Officer-Coordination', 9, 9, 9, 9, 9, 9, 9, 8, 9, 9, 'Visited Alamgir Hospital and worked with other departments like, emergency medical equipment, Ration store and food distribution point. He worked with other interns at iftar distribution, ihram house. He actively participated in the distribution of food to the needy patients and their attendants at Jinnah Hospital. He worked with our team for the packing of ration packages.', 'He was witty, respectful, obedient and cooperative individual who completed his tasks on time. He was a good team member and showed a possitive attitude during his stay at AWT.', 'Nisar Ahmed', 'Coordinator', NULL, NULL, NULL, NULL, NULL, NULL, 'bilal.shuja@lyceumschool.edu.pk', 'BSAF', NULL, '2016', NULL, '0334-3151441', NULL, 0, 'completed', NULL, NULL, 0, 0, 0, 0, 0, NULL, NULL, 'Rehan Shuja', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO interns (id, sname, sterm, sInstitute, Hours, dateassignfrom, dateassignto, dateprefferedfrom, dateprefferedto, DateofInternship, Dateofentry, Address, Organizationname, Mentor, Designationanddepartment, punctuality, regularity, productivity, relationship_with_others, Initiative, Maturity, Confidence, Analytical_ability, abilityhardword, knowledge, Assignedwork, comments, HRperson, HRdesignation, Request_Form, Photograph, CV, Recommendation_Letter, CNIC_copy, Student_ID, Email, Degree, Location, iyear, Date_of_Submission, Cellnumber, confirmed, Waiting, status, GroupName, GroupTime, Assignment1, Assignment2, Assignment3, Assignment4, Assignment5, Supervisor, Department, Father_name, GroupN, Summer, Certificate_Period_Detail, Remarks, Assignments, ERPNO) VALUES (374, 'Muhammad Immad Yasin', NULL, 'Institute of Business Administration', NULL, '2016-06-15 00:00:00', '2016-08-13 00:00:00', NULL, NULL, NULL, '2016-06-04 00:00:00', '3/251, Street no 17, Gold Villa, First Floor, Sharfabad, Karachi.', 'Institute of Business Administration', 'Mr. Muhammad Wali', 'Officer-Coordination', 8, 9, 9, 9, 9, 9, 9, 8, 9, 9, 'Imad took part in iftar packaging throughout Ramadan. He also contributed great time visiting the Ration store and the Ahram house. He captured pictures of various items at Ahram house to post it online for marketing. He also visited different departments and interviewed patients, who are availing free medical facilities at Alamgir. Apart from that he also participated lively in the distribution of food packets at Jinnah Hospital.', 'He has the ability to analyze problems and outline necessary course of action. He is an industrious person who is always ready to confront any challenges. He is really passionate about his work. He needs to have a little fun along with work.', 'Nisar Ahmed', 'Coordinator', NULL, NULL, NULL, NULL, NULL, NULL, 'immadyasin@gmail.com', 'BSAF', NULL, '2016', NULL, '0336-2388588,02138104700', NULL, 0, 'completed', NULL, NULL, 0