INSERT INTO interns (id, sname, sterm, sInstitute, Hours, dateassignfrom, dateassignto, dateprefferedfrom, dateprefferedto, DateofInternship, Dateofentry, Address, Organizationname, Mentor, Designationanddepartment, punctuality, regularity, productivity, relationship_with_others, Initiative, Maturity, Confidence, Analytical_ability, abilityhardword, knowledge, Assignedwork, comments, HRperson, HRdesignation, Request_Form, Photograph, CV, Recommendation_Letter, CNIC_copy, Student_ID, Email, Degree, Location, iyear, Date_of_Submission, Cellnumber, confirmed, Waiting, status, GroupName, GroupTime, Assignment1, Assignment2, Assignment3, Assignment4, Assignment5, Supervisor, Department, Father_name, GroupN, Summer, Certificate_Period_Detail, Remarks, Assignments, ERPNO) VALUES (389, 'Maleeha Rizwan', NULL, 'Institute of Business Administration', NULL, '2016-06-15 00:00:00', '2016-08-13 00:00:00', NULL, NULL, NULL, '2016-06-23 00:00:00', 'House no 66/2, Zulfiqar Street, 1-B, Phase VIII, DHA, Karachi.', 'Institute of Business Administration', 'Mr. Muhammad Wali', 'Officer-Coordination', 9, 9, 9, 9, 9, 9, 9, 8, 9, 9, 'Maleeha and her team were majorly assigned to the task of content writing for the AWT Annual Report 2016. She has demonstrated her apt writing and thinking skills tremendously through this task. Along with this, she has also completed volunteering in the active programs that AWT has held in Ramzan, mainly the Iftaar distribution as well as the ration distribution services.', 'She has shown great dedication and hardwork in her time here. We value volunteers who put all their effort in their work and it has really shown. Maleeha has been a vital part of the intern family at AWT and has proven to play an equally active role.', 'Nisar Ahmed', 'Coordinator', 0, NULL, NULL, 0, NULL, NULL, 'm.rizwan2009@live.com', 'BBA', NULL, '2016', NULL, '0321-8947072', NULL, 0, 'completed', NULL, NULL, 0, 0, 0, 0, 0, NULL, NULL, 'Rizwan Raza', NULL, NULL, NULL, NULL, NULL, NULL);
