INSERT INTO interns (id, sname, sterm, sInstitute, Hours, dateassignfrom, dateassignto, dateprefferedfrom, dateprefferedto, DateofInternship, Dateofentry, Address, Organizationname, Mentor, Designationanddepartment, punctuality, regularity, productivity, relationship_with_others, Initiative, Maturity, Confidence, Analytical_ability, abilityhardword, knowledge, Assignedwork, comments, HRperson, HRdesignation, Request_Form, Photograph, CV, Recommendation_Letter, CNIC_copy, Student_ID, Email, Degree, Location, iyear, Date_of_Submission, Cellnumber, confirmed, Waiting, status, GroupName, GroupTime, Assignment1, Assignment2, Assignment3, Assignment4, Assignment5, Supervisor, Department, Father_name, GroupN, Summer, Certificate_Period_Detail, Remarks, Assignments, ERPNO) VALUES (753, 'Usama Shabbir', '2nd Semester 1st Year', 'IBA', '6 Weeks', NULL, NULL, NULL, NULL, NULL, '2019-07-11 00:00:00', 'Flat # DD-22 !st Floor, Defence view Phase III, Karachi', 'Alamgir Welfare Trust International', 'Umer Qureshi', 'Asst. Coordinator', 9, 9, 9, 8, 8, 8, 7, 8, 9, 9, 'He interviewed beneficiaries at OPD to make patient stories for marketing purpose.He also participated  in sorting and uploading books at our online portal. He also participated in the thalassemia conference and the blood drive. He assisted in packaging of gift items for pilgrims of Hajj. He also suggested different ideas about our new venture Malbosaat.', 'He worked as a dedicated intern at AWT and never refused or made excuses on any assigned task. He suggested good ideas for new ventures. He was a good team member and efficient on his all assigned tasks.', 'Nisar Ahmed', 'Asst. Trustee & Coordinator', NULL, NULL, NULL, NULL, NULL, NULL, 'usamashabbir98@hotmail.com', 'BS AF', NULL, '2019', NULL, '0334-3511532', NULL, 0, 'completed', NULL, NULL, 0, 0, 0, 0, 0, NULL, NULL, 'Muhammad Shabbir', NULL, 0, '1st July 2019 till 18th August 2019', 'Interview Done', 'Translate Pg # 52,3', NULL);
