INSERT INTO interns (id, sname, sterm, sInstitute, Hours, dateassignfrom, dateassignto, dateprefferedfrom, dateprefferedto, DateofInternship, Dateofentry, Address, Organizationname, Mentor, Designationanddepartment, punctuality, regularity, productivity, relationship_with_others, Initiative, Maturity, Confidence, Analytical_ability, abilityhardword, knowledge, Assignedwork, comments, HRperson, HRdesignation, Request_Form, Photograph, CV, Recommendation_Letter, CNIC_copy, Student_ID, Email, Degree, Location, iyear, Date_of_Submission, Cellnumber, confirmed, Waiting, status, GroupName, GroupTime, Assignment1, Assignment2, Assignment3, Assignment4, Assignment5, Supervisor, Department, Father_name, GroupN, Summer, Certificate_Period_Detail, Remarks, Assignments, ERPNO) VALUES (756, 'Muhammad Umair Tasleem', '2nd semester 1st year', 'BHU', '6 weeks', NULL, NULL, NULL, NULL, NULL, '2019-07-17 00:00:00', 'Plot 260 street 17 BMCHS, Karachi', 'Alamgir Welfare Trust International', 'Umer Qureshi', 'Asst. Coordinator', 8, 8, 8, 9, 9, 9, 9, 8, 8, 8, 'He visited book bank to sort and arrange books for website. He sorted clothes and updated the system of Malboosat department and helped market the products. He also helped in packing of the packages at Alamgir Ahram House and also actively participated in activities such as food drive, blood donation drive. He interviewed beneficiaries at Marriage Assistance, OPD and Physiotherapy department for case studies.', 'He carried out his duties with utmost determination. He participated in the seminars and other drives which proved be a great act of welfare. We hope that he continues doing such acts of welfare in future as well.', 'Nisar Ahmed', 'Asst. Trustee & Coordinator', NULL, NULL, NULL, NULL, NULL, NULL, 'umairtasleem999@gmail', 'BSAF', NULL, '2019', NULL, '0321-2474697', NULL, 0, 'completed', NULL, NULL, 0, 0, 0, 0, 0, NULL, NULL, 'Taslim Anis', NULL, 0, '1st July 2019 till 18th August 2019', 'Interview Done', NULL, NULL);
